tool_call.arguments:
{"command": "for i in $(seq 1 8); do
  code=$(curl -s -o /dev/null --max-time 3 -w "%{http_code}" http://127.0.0.1:38489/ 2>/dev/null)
  [ "$code" = "200" ] && { echo "app UP at check $i"; break; }
  sleep 55
done
curl -s -o /dev/null --max-time 3 -w "app direct: %{http_code}\n" http://127.0.0.1:38489/ 2>/dev/null; free -m | sed -n '2p' | awk '{print "available="$6"MB"}'", "security_risk": "LOW", "summary": "Wait for app to be up"}
